outputs = ['kzfc', 'czzeya', 'jxg', 'weyizjac', 'waj']

print("Input -> Output:")
for i in range(len(inputs)):
    print(f"{inputs[i]} -> {outputs[i]}")

# Let's manually identify differences
print("\nDetailed analysis:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"Input: '{inp}' -> Output: '{out}'")

    # Find where they differ
    diff_positions = []
    for j in range(min(len(inp), len(out))):
        if inp[j] != out[j]:
            diff_positions.append((j, inp[j], out[j]))

    if len(inp) != len(out):
        if len(inp) > len(out):
            for j in range(len(out), len(inp)):
                diff_positions.append((j, inp[j], None))
        else:
            for j in range(len(inp), len(out)):
                diff_positions.append((j, None, out[j]))

    print(f"  Differences at positions: {diff_positions}")

