inputs = ['kefc', 'ceeya', 'jxg', 'wyadac', 'wd']
outputs = ['kzfc', 'czzeya', 'jxg', 'weyizjac', 'waj']

# Step 1: Find changed pairs
changed = []
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        changed.append((i, inputs[i], outputs[i]))

print("Changed pairs:", changed)

# Step 2: Analyze each changed pair
for idx, inp, outp in changed:
    print(f"\nPair {idx}: '{inp}' -> '{outp}'")

    # Find minimal edit
    # We'll manually look for the smallest change
    if len(inp) == len(outp):
        # Same length - find character differences
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")
    else:
        # Different lengths - need to identify insertion/deletion
        min_len = min(len(inp), len(outp))
        for i in range(min_len):
            if inp[i] != outp[i]:
                print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")
        if len(inp) > len(outp):
            for i in range(min_len, len(inp)):
                print(f"  Position {i}: '{inp[i]}' deleted")
        else:
            for i in range(min_len, len(outp)):
                print(f"  Position {i}: '{outp[i]}' inserted")

